-- 队列基础：带头结点链队列的首尾指针一致性。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '链队列','带头结点链队列在尾部插入、头部删除；删除最后一个结点后必须重置 rear。',course.id,parent.id,'cs408-linked-queue','AISTU',1,'REVIEWED',11,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-linked-queue' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-linked-queue',1,'REVIEWED','链队列',JSON_OBJECT('summary','带头结点链队列中 front 指向头结点，rear 指向最后一个数据结点。入队把新结点接到 rear.next 后更新 rear；出队删除 front.next。若删除的是最后一个数据结点，还必须令 rear=front，避免尾指针悬空。','steps',JSON_ARRAY('front 固定指向头结点','rear 指向最后一个数据结点','入队先连接 rear.next 再移动 rear','出队删除 front.next 指向的首数据结点','删除后为空时令 rear=front'),'prerequisite',JSON_OBJECT('contentKey','cs408-queue-fifo','title','队列的 FIFO 语义与基本操作','description','先掌握队尾入队与队头出队的职责。')),JSON_OBJECT('id','linked-queue-v1','prompt','带头结点链队列删除最后一个数据结点后，还必须执行什么？','options',JSON_ARRAY(JSON_OBJECT('id','RESET_REAR','text','令 rear = front，恢复空队列状态'),JSON_OBJECT('id','KEEP_REAR','text','保留 rear 指向已删除结点')),'correctOptionId','RESET_REAR','correctExplanation','正确：队列变空后首尾指针必须回到同一个头结点。','incorrectExplanation','不正确：保留 rear 会让它指向已删除结点，后续入队无法安全连接。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-linked-queue' AND existing.content_version=1 WHERE point.content_key='cs408-linked-queue' AND existing.id IS NULL;
